	/* @Override */
	public Stream<I> queryAllInterface<I>/* where I : TraceObjectInterface */(Lifespan span,
			Class<I> iface) {
		if (rootSchema == null) {
			return Stream.of();
		}
		PathFilter filter = rootSchema.searchFor(iface, true);
		return getValuePaths(span, filter).filter(p => {
			TraceObject @object = p.getDestination(getRootObject());
			if (@object == null) {
				Msg.error(this, "NULL VALUE! " + p.getLastEntry());
				return false;
			}
			return true;
		}).map(p => p.getDestination(getRootObject()).queryInterface(iface));
	}

	/* @Override */
	public void cullDisconnectedObjects() {
		using (LockHold hold = trace.lockWrite())
{
			foreach (DBTraceObject obj in objectStore.asMap().values()) {
				if (!obj.doIsConnected()) {
					obj.delete();
				}
			}
		}
	}

	/* @Override */
