	static bool acceptValue<I>/* where I : TraceObjectInterface */(DBTraceObjectValue value,
			string key, Class<I> ifaceCls, Predicate<I> predicate) {
		if (!value.hasEntryKey(key)) {
			return false;
		}
		TraceObject parent = value.getParent();
		I iface = parent.queryInterface(ifaceCls);
		if (iface == null) {
			return false;
		}
		if (!predicate.test(iface)) {
			return false;
		}
		return true;
	}

