	public BypassWriteCache withoutWriteCache() {
		wbCacheDisabled = true;
		return new _Anon_BypassWriteCache_2();
	}

	internal class _Anon_LinkedHashMap_1 : LinkedHashMap<>
	{

			protected bool removeEldestEntry(
					Map.Entry<ObjectsContainingKey, Collection<object>> eldest) {
				return size() > OBJECTS_CONTAINING_CACHE_SIZE;
			}
		
	}


	internal class _Anon_BypassWriteCache_2 : BypassWriteCache
	{

			/* @Override */
